import json
import urllib.request
import urllib.parse
import time

SESSION_ID = None
BASE_URL = "http://are-sidecar:8000/mcp"

def parse_sse(response_text):
    """Parse SSE response and extract JSON messages."""
    results = []
    current_event = None
    current_data = None
    for line in response_text.split('\n'):
        line = line.strip()
        if line.startswith('event:'):
            current_event = line.split(':', 1)[1].strip()
        elif line.startswith('data:'):
            current_data = line.split(':', 1)[1].strip()
            if current_data:
                try:
                    results.append(json.loads(current_data))
                except:
                    results.append(current_data)
                current_data = None
    return results

def mcp_call(method, params=None, is_notification=False):
    global SESSION_ID
    req_id = int(time.time() * 1000) % 100000
    payload = {
        "jsonrpc": "2.0",
        "method": method,
    }
    if params:
        payload["params"] = params
    if not is_notification:
        payload["id"] = req_id

    data = json.dumps(payload).encode('utf-8')
    headers = {
        'Content-Type': 'application/json',
        'Accept': 'application/json, text/event-stream',
    }
    if SESSION_ID:
        headers['mcp-session-id'] = SESSION_ID

    req = urllib.request.Request(BASE_URL, data=data, headers=headers, method='POST')
    try:
        resp = urllib.request.urlopen(req, timeout=30)
        # Capture session ID from response headers
        if not SESSION_ID:
            SESSION_ID = resp.headers.get('mcp-session-id')
        body = resp.read().decode('utf-8')
        results = parse_sse(body)
        if results:
            return results[0] if len(results) == 1 else results
        return None
    except Exception as e:
        print(f"Error: {e}")
        return None

def tool_call(tool_name, arguments=None):
    params = {"name": tool_name}
    if arguments:
        params["arguments"] = arguments
    return mcp_call("tools/call", params)

# Initialize
print("Initializing...")
result = mcp_call("initialize", {
    "protocolVersion": "2024-11-05",
    "capabilities": {},
    "clientInfo": {"name": "cli-client", "version": "1.0"}
})
